// Command intellijgen writes the IntelliJ plugin's keyword list from the
// compiler's lexer (ADR 0090 §2), so a new keyword reaches the plugin's
// highlighting or TestKeywordsAreCurrent fails:
//
//	go run ./tooling/intellijgen
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"fiig-lang/compiler/lexer"
)

// Target is the generated file, relative to the repository root.
const Target = "ide/intellij/src/main/kotlin/dev/fiig/intellij/FiigKeywords.kt"

// Generate is the file's contents.
func Generate() string {
	var b strings.Builder
	b.WriteString("// Code generated by `go run ./tooling/intellijgen`; DO NOT EDIT.\n")
	b.WriteString("// The compiler's reserved words (compiler/lexer), for highlighting.\n\n")
	b.WriteString("package dev.fiig.intellij\n\n")
	b.WriteString("object FiigKeywords {\n    val ALL: Set<String> = setOf(\n")
	for _, k := range lexer.Keywords() {
		fmt.Fprintf(&b, "        %q,\n", k)
	}
	b.WriteString("    )\n}\n")
	return b.String()
}

func main() {
	root := "."
	if len(os.Args) > 1 {
		root = os.Args[1]
	}
	path := filepath.Join(root, filepath.FromSlash(Target))
	if err := os.WriteFile(path, []byte(Generate()), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
